'use client';

import { useCallback, useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Wash } from '@/registry/ndeko/ui/wash';

import {
  ARTICLES,
  CATEGORIES,
  CATEGORY_GLYPH,
  CONTACT,
  POPULAR_IDS,
  SITE,
  type Article,
  type Category,
} from './data';
import { HelpSearch } from './help-search';
import { countIn, matchesOf, totalIn, wordsOf } from './match';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  suggestionsIn,
  type HelpState,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const CARD =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

const UNIT_LABELS = ['articles', 'article', 'matching'];

function isPopular(article: Article) {
  return POPULAR_IDS.includes(article.id);
}

const POPULAR = ARTICLES.filter(isPopular);

function unitOf(count: number, isSearching: boolean) {
  if (isSearching) {
    return 'matching';
  }
  if (count === 1) {
    return 'article';
  }
  return 'articles';
}

function categoryTitleOf(article: Article) {
  const category = CATEGORIES.find(
    (candidate) => candidate.id === article.category
  );
  return category?.title ?? '';
}

function matchLineOf(state: HelpState, count: number) {
  const hasWords = wordsOf(state.query).length > 0;
  const isListed = state.isOpen && hasWords;
  if (!isListed) {
    return '';
  }
  if (count === 0) {
    return 'No article matches';
  }
  if (count === 1) {
    return '1 article matches';
  }
  return `${count} articles match`;
}

type CategoryCardProps = {
  category: Category;
  count: number;
  isSearching: boolean;
};

function CategoryCard({ category, count, isSearching }: CategoryCardProps) {
  const Glyph = CATEGORY_GLYPH[category.id];
  const hasNone = isSearching && count === 0;

  return (
    <li>
      <a
        href={category.href}
        className={cn(
          CARD,
          'group hover:bg-foreground/[0.02] flex h-full items-start gap-3 p-4 transition-[opacity,background-color] duration-200',
          hasNone && 'opacity-45',
          FOCUS_RING
        )}
      >
        <span className='keycap-3d flex size-9 shrink-0 items-center justify-center rounded-lg'>
          <Glyph className='text-muted-foreground size-4' />
        </span>
        <span className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <span className='text-[13px] font-medium'>{category.title}</span>
          <span className='text-muted-foreground text-xs text-pretty'>
            {category.lead}
          </span>
        </span>
        <span className='text-muted-foreground flex shrink-0 items-baseline gap-1 text-xs tabular-nums'>
          <MotionNumber value={count} />
          <WordRoll text={unitOf(count, isSearching)} labels={UNIT_LABELS} />
        </span>
      </a>
    </li>
  );
}

export default function HelpCenter01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const topicsId = useId();
  const popularId = useId();
  const matches = matchesOf(state.query);
  const suggestions = suggestionsIn(state);
  const isSearching = wordsOf(state.query).length > 0;
  const matchLine = matchLineOf(state, matches.length);
  const message = spokenUnless(isAutoplaying, matchLine);
  const canReplay = isFinished && !isAutoplaying;

  const close = useCallback(() => act({ type: 'closed' }), [act]);

  function countOf(category: Category) {
    if (isSearching) {
      return countIn(matches, category.id);
    }
    return totalIn(category.id);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-10 px-4 py-6 @2xl:px-8 @2xl:py-8'>
          <header className='flex min-h-8 items-center gap-2'>
            <a
              href={SITE.homeHref}
              className={cn(
                'flex items-center gap-2 rounded-md text-sm font-semibold',
                FOCUS_RING
              )}
            >
              <CompanyMark seed={SITE.name} size='lg' />
              {SITE.name}
            </a>
            <span className='text-muted-foreground text-sm'>Help</span>
            <span className='flex-1' />
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </header>

          <section className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] relative isolate z-10 flex flex-col items-center gap-4 rounded-2xl px-5 py-10 text-center shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:py-14'>
            <Wash />
            <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
              How can we help?
            </h1>
            <p className='text-muted-foreground max-w-md text-sm text-pretty'>
              Search the guides, or start from a topic below.
            </p>
            <HelpSearch
              query={state.query}
              isOpen={state.isOpen}
              activeIndex={state.activeIndex}
              suggestions={suggestions}
              matchCount={matches.length}
              pressed={pressed}
              isDemonstrating={isAutoplaying}
              onType={(value) => act({ type: 'typed', value })}
              onFocus={() => act({ type: 'focused' })}
              onMove={(by) => act({ type: 'moved', by })}
              onEscape={() => act({ type: 'escaped' })}
              onClose={close}
            />
          </section>

          <section aria-labelledby={topicsId} className='flex flex-col gap-3'>
            <h2 id={topicsId} className='px-1 text-[13px] font-medium'>
              Topics
            </h2>
            <ul className='grid gap-3 @lg:grid-cols-2 @3xl:grid-cols-3'>
              {CATEGORIES.map((category) => (
                <CategoryCard
                  key={category.id}
                  category={category}
                  count={countOf(category)}
                  isSearching={isSearching}
                />
              ))}
            </ul>
          </section>

          <div className='grid gap-10 @3xl:grid-cols-[minmax(0,1fr)_20rem] @3xl:gap-8'>
            <section
              aria-labelledby={popularId}
              className='flex flex-col gap-3'
            >
              <h2 id={popularId} className='px-1 text-[13px] font-medium'>
                Popular articles
              </h2>
              <ul className={cn(CARD, 'flex flex-col p-1')}>
                {POPULAR.map((article) => (
                  <li key={article.id}>
                    <a
                      href={article.href}
                      className={cn(
                        'group hover:bg-foreground/[0.03] flex items-center gap-3 rounded-lg px-3 py-2.5 transition-colors duration-100',
                        FOCUS_RING
                      )}
                    >
                      <span className='flex min-w-0 flex-1 flex-col gap-0.5'>
                        <span className='truncate text-[13px] font-medium'>
                          {article.title}
                        </span>
                        <span className='text-muted-foreground text-xs'>
                          {categoryTitleOf(article)}
                        </span>
                      </span>
                      <ChevronRightIcon className='text-muted-foreground size-4 shrink-0 transition-transform duration-100 group-hover:translate-x-0.5' />
                    </a>
                  </li>
                ))}
              </ul>
            </section>

            <section
              aria-label='Contact support'
              className={cn(CARD, 'flex flex-col gap-4 self-start p-5')}
            >
              <div className='flex items-center gap-3'>
                <Avatar seed={CONTACT.person} className='size-10' />
                <div className='flex min-w-0 flex-col'>
                  <p className='text-sm font-medium'>{CONTACT.person}</p>
                  <p className='text-muted-foreground text-xs'>
                    {CONTACT.role}
                  </p>
                </div>
              </div>
              <div className='flex flex-col gap-1'>
                <p className='text-[13px] font-medium'>Still stuck?</p>
                <p className='text-muted-foreground text-[13px] text-pretty'>
                  {CONTACT.lead}
                </p>
                <p className='text-muted-foreground text-xs'>{CONTACT.hours}</p>
              </div>
              <div className='flex flex-wrap gap-2'>
                <Button
                  nativeButton={false}
                  render={<a href={CONTACT.chatHref} />}
                >
                  Start a chat
                </Button>
                <Button
                  variant='outline'
                  nativeButton={false}
                  render={<a href={CONTACT.emailHref} />}
                >
                  Email us
                </Button>
              </div>
            </section>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useEffect, useId, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon, SearchIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  INSTANT,
  SPRING,
} from '@/registry/ndeko/lib/motion-presets';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Input } from '@/registry/ndeko/ui/input';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import { CATEGORIES, SITE, type Article } from './data';
import { markedPartsOf, wordsOf } from './match';

const LIST_SHOWN = { opacity: 1, scale: 1 };

const LIST_HIDDEN = { opacity: 0, scale: 0.97 };

const LIST_FADED = { opacity: 0, scale: 1 };

const LIST_ARRIVE: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const LIST_LEAVE: Transition = { duration: 0.1, ease: EASE_OUT_STRONG };

const KEY_MOTION = 'transition-[scale] duration-150';

function listStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return LIST_FADED;
  }
  return LIST_HIDDEN;
}

function travelOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return SPRING;
}

function optionIdOf(listId: string, index: number) {
  return `${listId}-${index}`;
}

function activeIdOf(listId: string, activeIndex: number, isListed: boolean) {
  const hasActive = activeIndex >= 0;
  if (!isListed || !hasActive) {
    return undefined;
  }
  return optionIdOf(listId, activeIndex);
}

function categoryTitleOf(article: Article) {
  const category = CATEGORIES.find(
    (candidate) => candidate.id === article.category
  );
  return category?.title ?? '';
}

function allResultsLineOf(count: number, query: string) {
  const trimmed = query.trim();
  if (count === 1) {
    return `See the 1 result for “${trimmed}”`;
  }
  return `See all ${count} results for “${trimmed}”`;
}

function MarkedTitle({ title, words }: { title: string; words: string[] }) {
  const parts = markedPartsOf(title, words);

  return (
    <span className='min-w-0 truncate'>
      {parts.map((part) => {
        if (part.isMatch) {
          return (
            <mark
              key={part.key}
              className='bg-primary/15 text-foreground rounded-[3px]'
            >
              {part.text}
            </mark>
          );
        }
        return <span key={part.key}>{part.text}</span>;
      })}
    </span>
  );
}

type HelpSearchProps = {
  query: string;
  isOpen: boolean;
  activeIndex: number;
  suggestions: Article[];
  /** All the articles that match, of which the first few are suggested. */
  matchCount: number;
  pressed: string | null;
  /** While the demonstration plays, the suggestions show without the focus and a click elsewhere leaves them be. */
  isDemonstrating: boolean;
  onType: (value: string) => void;
  onFocus: () => void;
  onMove: (by: 1 | -1) => void;
  onEscape: () => void;
  onClose: () => void;
};

export function HelpSearch({
  query,
  isOpen,
  activeIndex,
  suggestions,
  matchCount,
  pressed,
  isDemonstrating,
  onType,
  onFocus,
  onMove,
  onEscape,
  onClose,
}: HelpSearchProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const wrapperRef = useRef<HTMLDivElement>(null);
  const inputId = useId();
  const listId = useId();
  const words = wordsOf(query);
  const hasWords = words.length > 0;
  const isShown = isOpen && hasWords;
  const hasSuggestions = suggestions.length > 0;
  const isListed = isShown && hasSuggestions;
  const activeId = activeIdOf(listId, activeIndex, isListed);
  const listensOutside = isShown && !isDemonstrating;

  useEffect(() => {
    if (!listensOutside) {
      return;
    }
    function closeFromOutside(event: PointerEvent) {
      const wrapper = wrapperRef.current;
      const target = event.target;
      const isInside = target instanceof Node && wrapper?.contains(target);
      if (!isInside) {
        onClose();
      }
    }
    document.addEventListener('pointerdown', closeFromOutside);
    return () => document.removeEventListener('pointerdown', closeFromOutside);
  }, [listensOutside, onClose]);

  function openActive() {
    let index = activeIndex;
    if (index < 0) {
      index = 0;
    }
    const optionId = optionIdOf(listId, index);
    const option = document.getElementById(optionId);
    option?.click();
  }

  function handleKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      onMove(1);
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      onMove(-1);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onEscape();
      return;
    }
    const isEnter = event.key === 'Enter';
    if (isEnter && isListed) {
      event.preventDefault();
      openActive();
    }
  }

  function closeWhenLeaving(event: React.FocusEvent<HTMLDivElement>) {
    const next = event.relatedTarget;
    const staysInside =
      next instanceof Node && event.currentTarget.contains(next);
    if (!staysInside) {
      onClose();
    }
  }

  return (
    <div
      ref={wrapperRef}
      onBlur={closeWhenLeaving}
      className='relative w-full max-w-xl text-start'
    >
      <label htmlFor={inputId} className='sr-only'>
        Search the help center
      </label>
      <SearchIcon className='text-muted-foreground pointer-events-none absolute start-4 top-1/2 size-[18px] -translate-y-1/2' />
      <Input
        id={inputId}
        type='search'
        role='combobox'
        autoComplete='off'
        spellCheck={false}
        aria-autocomplete='list'
        aria-expanded={isListed}
        aria-controls={listId}
        aria-activedescendant={activeId}
        placeholder='Search payroll, people, taxes'
        value={query}
        onChange={(event) => onType(event.target.value)}
        onFocus={onFocus}
        onKeyDown={handleKeys}
        className='h-12 rounded-xl ps-11 pe-4 md:text-sm'
      />
      <AnimatePresence initial={false}>
        {isShown && (
          <motion.div
            key='suggestions'
            initial={listStartOf(shouldReduceMotion)}
            animate={LIST_SHOWN}
            exit={{
              ...listStartOf(shouldReduceMotion),
              transition: LIST_LEAVE,
            }}
            transition={LIST_ARRIVE}
            className='surface-raised absolute inset-x-0 top-full z-20 mt-2 flex origin-top flex-col rounded-xl p-1'
          >
            {hasSuggestions && (
              <ul
                id={listId}
                role='listbox'
                aria-label='Suggested articles'
                className='flex flex-col'
              >
                {suggestions.map((article, index) => {
                  const isActive = index === activeIndex;
                  return (
                    <li key={article.id} role='none'>
                      <a
                        id={optionIdOf(listId, index)}
                        role='option'
                        aria-selected={isActive}
                        href={article.href}
                        tabIndex={-1}
                        onMouseDown={(event) => event.preventDefault()}
                        className='relative isolate flex min-h-11 flex-col justify-center gap-0.5 rounded-lg px-3 py-1.5 outline-none'
                      >
                        {isActive && (
                          <motion.span
                            layoutId={`${listId}-highlight`}
                            transition={travelOf(shouldReduceMotion)}
                            className='bg-foreground/[0.06] absolute inset-0 -z-10 rounded-lg'
                          />
                        )}
                        <span className='flex items-center gap-2 text-[13px] font-medium'>
                          <MarkedTitle title={article.title} words={words} />
                        </span>
                        <span className='text-muted-foreground text-xs'>
                          {categoryTitleOf(article)}
                        </span>
                      </a>
                    </li>
                  );
                })}
              </ul>
            )}
            {!hasSuggestions && (
              <p className='text-muted-foreground px-3 py-3 text-[13px] text-pretty'>
                No article mentions these words yet. Try another word, or write
                to us below.
              </p>
            )}
            <div className='flex flex-wrap items-center gap-x-3 gap-y-2 px-3 pt-2 pb-1.5'>
              {hasSuggestions && (
                <a
                  href={SITE.searchHref}
                  className={cn(
                    'text-primary-ink inline-flex items-center gap-1 rounded-sm text-xs font-medium',
                    FOCUS_RING
                  )}
                >
                  {allResultsLineOf(matchCount, query)}
                  <ArrowRightIcon className='size-3.5' />
                </a>
              )}
              <p
                aria-hidden='true'
                className='text-muted-foreground ms-auto flex items-center gap-1 text-xs'
              >
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-up')
                  )}
                >
                  ↑
                </Kbd>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-down')
                  )}
                >
                  ↓
                </Kbd>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-escape')
                  )}
                >
                  Esc
                </Kbd>
              </p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { matchesOf } from './match';

export type HelpState = {
  query: string;
  isOpen: boolean;
  /** The suggestion Enter opens. Nothing is highlighted before the arrows are used. */
  activeIndex: number;
};

export type HelpAction =
  | { type: 'typed'; value: string }
  | { type: 'focused' }
  | { type: 'moved'; by: 1 | -1 }
  | { type: 'escaped' }
  | { type: 'closed' };

type Step = SessionStep<HelpState, HelpAction>;

export const SUGGESTION_LIMIT = 5;

const NOTHING_HIGHLIGHTED = -1;

export const INITIAL: HelpState = {
  query: '',
  isOpen: false,
  activeIndex: NOTHING_HIGHLIGHTED,
};

export function suggestionsIn(state: HelpState) {
  const matches = matchesOf(state.query);
  return matches.slice(0, SUGGESTION_LIMIT);
}

/** The first arrow lands on the first or the last row, then the highlight wraps around the list. */
function nextIndexOf(current: number, by: 1 | -1, count: number) {
  if (current === NOTHING_HIGHLIGHTED) {
    if (by === 1) {
      return 0;
    }
    return count - 1;
  }
  const moved = current + by + count;
  return moved % count;
}

function moved(state: HelpState, by: 1 | -1): HelpState {
  const count = suggestionsIn(state).length;
  if (count === 0) {
    return state;
  }
  if (!state.isOpen) {
    const firstIndex = nextIndexOf(NOTHING_HIGHLIGHTED, by, count);
    return { ...state, isOpen: true, activeIndex: firstIndex };
  }
  const activeIndex = nextIndexOf(state.activeIndex, by, count);
  return { ...state, activeIndex };
}

/** Escape closes the suggestions first, and clears the field when they are already closed. */
function escaped(state: HelpState): HelpState {
  if (state.isOpen) {
    return { ...state, isOpen: false, activeIndex: NOTHING_HIGHLIGHTED };
  }
  return INITIAL;
}

export function reducer(state: HelpState, action: HelpAction): HelpState {
  switch (action.type) {
    case 'typed':
      return {
        query: action.value,
        isOpen: true,
        activeIndex: NOTHING_HIGHLIGHTED,
      };
    case 'focused':
      return { ...state, isOpen: true };
    case 'moved':
      return moved(state, action.by);
    case 'escaped':
      return escaped(state);
    case 'closed':
      return { ...state, isOpen: false, activeIndex: NOTHING_HIGHLIGHTED };
  }
}

const QUERY = 'payslip';

const KEY_MS = 110;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function arrow(after: number, by: 1 | -1): Step {
  let press = 'key-down';
  if (by === -1) {
    press = 'key-up';
  }
  return { after, by: 'demo', press, action: { type: 'moved', by } };
}

/**
 * Someone types a word slowly enough for the counts below to follow each letter, walks the
 * suggestions, and leaves with Escape twice: the round ends on the empty field it started from.
 */
export const SCRIPT: Step[] = [
  ...typing(QUERY, 1500),
  arrow(1400, 1),
  arrow(700, 1),
  {
    after: 2000,
    by: 'demo',
    press: 'key-escape',
    action: { type: 'escaped' },
  },
  { after: 900, by: 'demo', action: { type: 'escaped' } },
];

/** Under reduced motion the word is typed, the counts show the matches and the best one is highlighted. */
export const RESTING: HelpState = {
  query: QUERY,
  isOpen: true,
  activeIndex: 0,
};

export const LOOP_AFTER_MS = 2600;

import { ARTICLES, type Article, type CategoryId } from './data';

export type MarkedPart = {
  key: string;
  text: string;
  isMatch: boolean;
};

type Range = {
  start: number;
  end: number;
};

type Scored = {
  article: Article;
  order: number;
  score: number;
};

/** A single letter matches half the help center, so a word counts from two letters. */
const MIN_WORD_LENGTH = 2;

export function wordsOf(query: string) {
  const lowered = query.toLowerCase();
  const pieces = lowered.split(/\s+/);
  return pieces.filter((piece) => piece.length >= MIN_WORD_LENGTH);
}

function rangesOfWord(lowered: string, word: string) {
  const ranges: Range[] = [];
  let start = lowered.indexOf(word);
  while (start !== -1) {
    const end = start + word.length;
    ranges.push({ start, end });
    start = lowered.indexOf(word, end);
  }
  return ranges;
}

function byStart(first: Range, second: Range) {
  return first.start - second.start;
}

function mergedRanges(ranges: Range[]) {
  const sorted = [...ranges].sort(byStart);
  const merged: Range[] = [];
  for (const range of sorted) {
    const last = merged.at(-1);
    const overlaps = last !== undefined && range.start <= last.end;
    if (overlaps) {
      last.end = Math.max(last.end, range.end);
      continue;
    }
    merged.push({ ...range });
  }
  return merged;
}

export function markedPartsOf(text: string, words: string[]) {
  const lowered = text.toLowerCase();
  const ranges = words.flatMap((word) => rangesOfWord(lowered, word));
  const parts: MarkedPart[] = [];
  let cursor = 0;
  for (const range of mergedRanges(ranges)) {
    if (range.start > cursor) {
      const plain = text.slice(cursor, range.start);
      parts.push({ key: String(cursor), text: plain, isMatch: false });
    }
    const match = text.slice(range.start, range.end);
    parts.push({ key: String(range.start), text: match, isMatch: true });
    cursor = range.end;
  }
  if (cursor < text.length) {
    const rest = text.slice(cursor);
    parts.push({ key: String(cursor), text: rest, isMatch: false });
  }
  return parts;
}

/** Every typed word must be found in the title or in the other words people use for it. */
function scoreOf(article: Article, words: string[]) {
  const title = article.title.toLowerCase();
  const haystack = `${title} ${article.terms}`;
  const isMatch = words.every((word) => haystack.includes(word));
  if (!isMatch) {
    return 0;
  }
  const inTitle = words.filter((word) => title.includes(word));
  return 1 + inTitle.length;
}

function byScoreThenOrder(first: Scored, second: Scored) {
  const scoreGap = second.score - first.score;
  if (scoreGap !== 0) {
    return scoreGap;
  }
  return first.order - second.order;
}

/** Articles that hold every typed word, the ones that say it in their title first. */
export function matchesOf(query: string) {
  const words = wordsOf(query);
  if (words.length === 0) {
    return [];
  }
  const scored = ARTICLES.map((article, order) => ({
    article,
    order,
    score: scoreOf(article, words),
  }));
  const matching = scored.filter((entry) => entry.score > 0);
  matching.sort(byScoreThenOrder);
  return matching.map((entry) => entry.article);
}

export function totalIn(category: CategoryId) {
  const inCategory = ARTICLES.filter(
    (article) => article.category === category
  );
  return inCategory.length;
}

export function countIn(matches: Article[], category: CategoryId) {
  const inCategory = matches.filter((article) => article.category === category);
  return inCategory.length;
}

